css:
/* Вкладки с переезжающей подложкой. Подложка — белая «таблетка» с рамкой primary: цвет текста вкладок не меняется,
   поэтому контраст надписей одинаков во всех состояниях; рамка подложки — от 3:1 к дорожке (видно, что выбрано). */
.tbi {
  --tbi-dur: 250ms;                           /* переезд подложки */
  --tbi-ease: cubic-bezier(.65, 0, .35, 1);   /* перемещение — разгон и торможение */
  --tbi-pad: 4px;
  --tbi-track: var(--surface, #eef0f3);
  --tbi-pill: var(--background, #ffffff);
  --tbi-edge: var(--primary, #2446d8);
  padding-block: 64px;
}
.tbi__title { margin: 0 0 24px; font-size: clamp(28px, 3.4vw, 44px); line-height: 1.15; }
.tbi__list {
  position: relative;
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr;  /* вкладки одной ширины */
  width: fit-content; max-width: 100%;
  margin: 0 0 24px; padding: var(--tbi-pad);
  border-radius: 999px;
  background: var(--tbi-track);
}
.tbi:not(.is-ready) .tbi__list { display: none; }   /* без JS переключать нечем — видны все панели */
.tbi__ind {
  position: absolute; top: var(--tbi-pad); bottom: var(--tbi-pad); left: var(--tbi-pad);
  width: calc((100% - 2 * var(--tbi-pad)) / var(--tbi-n, 2));
  border-radius: 999px;
  background: var(--tbi-pill);
  box-shadow: inset 0 0 0 2px var(--tbi-edge), 0 1px 3px rgba(16, 24, 40, .12);
  transform: translateX(calc(var(--tbi-i, 0) * 100%)); /* для dir="rtl" — умножайте на -100% */
  transition: transform var(--tbi-dur) var(--tbi-ease);
}
.tbi__tab {
  position: relative; z-index: 1;
  min-height: 44px; padding: 10px 20px;
  border: 0; border-radius: 999px; background: transparent;
  color: var(--text, #15171c); font: inherit; font-weight: 600; white-space: nowrap; cursor: pointer;
}
.tbi__tab:focus-visible { outline: 2px solid var(--tbi-edge); outline-offset: 3px; }
.tbi__save { margin-left: 6px; padding: 2px 8px; border-radius: 999px; background: var(--accent, #ffd23f); color: var(--on-accent, #15171c); font-size: .8em; }
.tbi__panels { display: grid; gap: 24px; }
.tbi.is-ready .tbi__panels { gap: 0; }
.tbi.is-ready .tbi__panel { grid-area: 1 / 1; }                     /* панели лежат друг на друге в одной ячейке */
.tbi.is-ready .tbi__panel[hidden] { display: block; visibility: hidden; } /* скрытая держит высоту, но не видна, не в Tab и не в дереве доступности */
.tbi__panel:focus-visible { outline: 2px solid var(--tbi-edge); outline-offset: 4px; border-radius: 4px; }
.tbi__price { margin: 0 0 8px; font-size: clamp(32px, 4vw, 48px); font-weight: 700; line-height: 1.1; font-variant-numeric: tabular-nums; }
.tbi__price span { font-size: 16px; font-weight: 400; color: var(--text-muted, #555b66); }
.tbi__desc { margin: 0; max-width: 48ch; color: var(--text-muted, #555b66); }
/* Смена панели: старая гаснет 120ms с разгоном, новая через 110ms поднимается на 8px и проявляется за 250ms.
   Перехлёста почти нет: текст двух панелей в одном месте при наложении «двоится» (цена поверх цены) */
.tbi__panel { transition: opacity 120ms cubic-bezier(.4, 0, 1, 1); }
.tbi__panel.is-out { opacity: 0; }
.tbi__panel.is-pre { opacity: 0; transform: translateY(8px); transition: none; }
.tbi__panel.is-in { transition: opacity 250ms cubic-bezier(.2, 0, 0, 1) 110ms, transform 250ms cubic-bezier(.2, 0, 0, 1) 110ms; }
/* Уменьшение движения (уровень «смягчить»): подложка встаёт на место сразу, панели меняются только прозрачностью за 150ms */
@media (prefers-reduced-motion: reduce) {
  .tbi__ind { transition: none; }
  .tbi__panel.is-pre { transform: none; }
  .tbi__panel.is-in { transition: opacity 150ms linear 110ms; }
}
/* Контрастная тема Windows: рамку подложки рисуем системным цветом, иначе выбранную вкладку не отличить */
@media (forced-colors: active) {
  .tbi__ind { box-shadow: none; outline: 2px solid Highlight; outline-offset: -2px; }
}

js:
// Вкладки с переезжающей подложкой: без зависимостей. Шаблон WAI-ARIA Tabs: стрелки, Home/End, выбор следует за фокусом.
(() => {
  document.querySelectorAll('[data-tbi]').forEach((root) => {
    const list = root.querySelector('[role="tablist"]');
    const tabs = list ? [...list.querySelectorAll('[role="tab"]')] : [];
    const panels = tabs.map((t) => document.getElementById(t.getAttribute('aria-controls')));
    if (!tabs.length || panels.some((p) => !p)) return; // разметка не сошлась — остаются все панели подряд
    let cur = Math.max(0, tabs.findIndex((t) => t.getAttribute('aria-selected') === 'true'));
    const show = (i, focus) => {
      tabs.forEach((t, k) => { t.setAttribute('aria-selected', String(k === i)); t.tabIndex = k === i ? 0 : -1; });
      if (focus) tabs[i].focus();
      list.style.setProperty('--tbi-i', i); // подложку двигает CSS-переход
      if (i === cur) return;
      const old = panels[cur], next = panels[i];
      cur = i;
      clearTimeout(old._t); // старая гаснет и прячется после перехода
      old.classList.remove('is-in'); old.classList.add('is-out');
      old._t = setTimeout(() => { old.hidden = true; old.classList.remove('is-out'); }, 120);
      clearTimeout(next._t); // новая: мгновенно в исходное положение, потом переход к видимой
      next.classList.remove('is-out', 'is-in'); next.hidden = false; next.classList.add('is-pre');
      void next.offsetWidth; // зафиксировать исходное положение до перехода
      next.classList.replace('is-pre', 'is-in');
    };
    list.style.setProperty('--tbi-n', tabs.length);
    panels.forEach((p, k) => { p.hidden = k !== cur; });
    tabs.forEach((t, k) => t.addEventListener('click', () => show(k)));
    list.addEventListener('keydown', (e) => {
      const n = tabs.length, k = { ArrowRight: cur + 1, ArrowLeft: cur - 1, Home: 0, End: n - 1 }[e.key];
      if (k === undefined) return;
      e.preventDefault();
      show((k + n) % n, true);
    });
    show(cur);
    root.classList.add('is-ready');
  });
})();
